pages=['index.html','Research.html','Team.html','Profile.html','Publications.html','News.html','Opportunity.html']
for name in pages:
 p=Path(name);s=p.read_text()
 s=s.replace('Structural biology & molecular discovery','Bacterial immunity &amp; structural biology')
 s=s.replace('Structural biology. Molecular discovery.','Antiphage defense. Molecular mechanisms.')
 s=re.sub(r'href="assets/css/site.css(?:\?[^\"]*)?"','href="assets/css/site.css?v=antiphage-20261104"',s)
 s=re.sub(r'href="assets/css/pages.css(?:\?[^\"]*)?"','href="assets/css/pages.css?v=antiphage-20261104"',s)
 if name in ['Team.html','Profile.html']:
  s=s.replace('2021 (Feb-Oct):','February 2021 – March 2022:').replace('2006-2009:','2011–2013:')
  s=s.replace('2024 to 2025:','2024–2025:').replace('2022 - 2024:','2022–2024:').replace('2015-2021:','2015–2021:').replace('2013-2015:','2013–2015:')
 p.write_text(s)
p=Path('index.html');s=p.read_text()
s=s.replace('<title>Home | Majumder Lab</title>','<title>Majumder Lab | Bacterial Antiphage Defense</title><meta name="description" content="The Majumder Lab at IIT Kharagpur studies bacterial antiphage defense through structural biology, biophysics, biochemistry, and microbiology.">')
s=s.replace('STRUCTURAL BIOLOGY / MAJUMDER LAB','BACTERIAL IMMUNITY / IIT KHARAGPUR')
s=s.replace('Life at the molecular scale.<br><em>Discovery without limits.</em>','Bacterial antiphage defense.<br><em>Mechanisms in molecular detail.</em>')
s=s.replace('Welcome to Majumder Lab at IIT Kharagpur. We explore the molecular machinery behind bacterial antiviral defense.','How do bacteria detect phage infection and stop it from spreading? We investigate the proteins, signals, and molecular assemblies that make bacterial immunity work.')
s=s.replace('Curiosity meets<br><em>molecular discovery.</em>','How an infection signal<br><em>becomes a defense response.</em>')
a=s.index('<div class="intro"><p>');b=s.index('</p></div>',a)+len('</p></div>')
s=s[:a]+'''<div class="intro"><p>The Majumder Lab at IIT Kharagpur investigates the molecular mechanisms of bacterial antiphage defense. We combine structural biology, biophysics, biochemistry, and microbiology to understand how immune proteins recognize signals and activate a response to infection.</p><p>Our work on CRISPR-associated effectors reveals how bacteria open membrane pores, remodel cellular metabolites, and assemble protein filaments to restrict phage replication. Using cryo-EM, X-ray crystallography, and functional experiments, we connect molecular structures to the defense strategies they enable.</p></div>'''+s[b:]
s=s.replace('<h3>Microscopy</h3><p>Single-particle cryo-EM of protein molecules.</p>','<h3>Resolve the structure</h3><p>Cryo-EM and X-ray crystallography reveal immune proteins and their assemblies.</p>')
s=s.replace('<h3>X-ray crystallography</h3><p>Resolving molecular structures at the atomic scale.</p>','<h3>Define the mechanism</h3><p>Biochemistry and biophysics connect immune signals to protein activity.</p>')
s=s.replace('<h3>Biochemistry</h3><p>Connecting protein structure to biological function.</p>','<h3>Test the defense</h3><p>Microbiology links molecular mechanisms to bacterial antiphage function.</p>')
s=s.replace('Bring your curiosity.<br><em>Build something together.</em>','Explore bacterial immunity.<br><em>Join the investigation.</em>')
s=s.replace('<section class="container link-grid">','''<section class="container defense-focus" aria-labelledby="defense-focus-heading"><p class="eyebrow">OUR RESEARCH</p><h2 id="defense-focus-heading">Three routes to<br><em>antiphage defense.</em></h2><div class="defense-focus-grid"><a href="Research.html#membrane-effectors"><span class="eyebrow">MEMBRANE EFFECTORS</span><h3>Control ion flow</h3><p>How Cap1, Chp1, and Cam1 connect immune signals to membrane depolarization.</p><span class="focus-link">Explore membrane pores ↗</span></a><a href="Research.html#cad1"><span class="eyebrow">METABOLIC EFFECTORS</span><h3>Change cellular chemistry</h3><p>How Cad1 converts ATP to ITP to arrest infected-cell growth.</p><span class="focus-link">Explore Cad1 ↗</span></a><a href="Research.html#cat1"><span class="eyebrow">SUPRAMOLECULAR ASSEMBLIES</span><h3>Build an active defense</h3><p>How Cat1 filament networks drive NAD depletion during CRISPR immunity.</p><span class="focus-link">Explore Cat1 ↗</span></a></div></section><section class="container link-grid">''')
p.write_text(s)
p=Path('Research.html');s=p.read_text()
s=s.replace('Explore Puja Majumder’s structural biology research into bacterial antiviral defense, CRISPR effectors, and membrane transporters.','Molecular mechanisms of bacterial antiphage defense at the Majumder Lab: immune signalling, CRISPR effectors, membrane pores, and supramolecular assemblies.')
s=s.replace('Small molecules.<br>Extraordinary<br><em>defense strategies.</em>','From immune signals<br>to <em>antiphage defense.</em>')
s=s.replace('Decoding the molecular machinery behind bacterial immunity.','We investigate how bacterial immune proteins turn the detection of phage infection into a molecular response that restricts viral replication.')
s=s.replace('See the structure.<br><em>Understand the story.</em>','Resolve the structure.<br><em>Explain the defense.</em>')
s=s.replace('We explore how bacteria sense viral threats and activate a remarkably diverse molecular arsenal. Combining structural biology, biophysics, biochemistry, and microbiology, we connect the architecture of proteins to the mechanisms that make them work.','Our central question is how bacterial antiphage defense systems are activated and how their effectors work. Combining structural biology, biophysics, biochemistry, and microbiology, we investigate immune signalling, membrane pore activation, metabolic changes, and protein assembly.')
a=s.index('<div class="detail-copy"><p>My research is centered');b=s.index('</p></div>',a)+len('</p></div>')
s=s[:a]+'''<div class="detail-copy"><p>We investigate the molecular steps that connect immune recognition to antiphage activity. Our approach combines biochemical characterization of defense proteins, measurements of their interactions with signalling molecules, and structural analysis of inactive and active states. Structure-guided experiments then test how specific molecular changes control protein function.</p><p>A major focus is the cyclic oligoadenylate-activated CARF effectors of type III CRISPR-Cas systems. These proteins can halt phage propagation by depolarizing the membrane, changing cellular nucleotide pools, or depleting NAD through supramolecular assembly. We study soluble and membrane proteins as well as large complexes, using antibody fragments and nanobodies when needed to enable structural analysis.</p><p>Our earlier work on the QacA multidrug efflux transporter established a foundation in membrane protein structure and function. The projects below trace our work from antibacterial transport to the molecular mechanisms of bacterial antiphage defense.</p></div>'''+s[b:]
s=s.replace('Molecular insights.<br><em>Biological impact.</em>','Molecular mechanisms<br><em>of bacterial defense.</em>')
s=s.replace('Exploring the versatility of bacterial defense, from signal recognition to cellular response.','Research on membrane pores, metabolic effectors, and filament assemblies, alongside our earlier work on antibacterial transport.')
s=s.replace('<nav class="project-nav" aria-label="Jump to a research project">','<nav class="project-nav" aria-label="Jump to a research project"><a href="#cap1">Cap1 <span>↗</span></a><a href="#chp1">Chp1 <span>↗</span></a>')
needle='<article class="project" id="cat1">'
new='''<section class="membrane-effectors" id="membrane-effectors" aria-labelledby="membrane-heading"><div class="section-heading"><div><p class="eyebrow">CYCLIC SIGNALS AND MEMBRANE IMMUNITY</p><h2 id="membrane-heading">Two ways to<br><em>activate a membrane pore.</em></h2></div><p>Cap1 and Chp1 connect cyclic oligoadenylate recognition to ion flow through distinct molecular mechanisms.</p></div><div class="membrane-grid"><article id="cap1"><p class="eyebrow">SIGNAL ACTIVATED PORE OPENING</p><h3>Cap1</h3><h4>Opening a preformed pore</h4><p>Cyclic tetra-adenylate binding triggers conformational changes in tetrameric Cap1 that widen its transmembrane pore. Activation leads to membrane depolarization and growth arrest, limiting phage replication.</p><a class="paper-link" href="https://www.biorxiv.org/content/10.1101/2025.11.13.688252v1">Read the bioRxiv preprint ↗</a><p class="research-status">Accepted in <em>Nature Structural &amp; Molecular Biology</em></p></article><article id="chp1"><p class="eyebrow">LIPID GATED PORE ACTIVATION</p><h3>Chp1</h3><h4>Removing a lipid barrier</h4><p>Cyclic oligoadenylate binding rearranges Chp1 to close lipid-accessible fenestrations and remove lipid obstruction of the pore. The resulting change in pore accessibility permits ion flow and membrane depolarization during antiphage defense.</p><a class="paper-link" href="https://www.biorxiv.org/content/10.64898/2026.08.05.743128v1">Read the bioRxiv preprint ↗</a><p class="research-status">Preprint · 2026</p></article></div></section>'''
assert s.count(needle)==1;s=s.replace(needle,new+needle)
s=s.replace('Curious about the<br><em>bigger picture?</em>','Explore the evidence<br><em>behind the mechanisms.</em>')
p.write_text(s)
p=Path('Opportunity.html');s=p.read_text().replace('Great questions.<br><em>Shared discoveries.</em>','Investigate bacterial immunity.<br><em>Shape the next questions.</em>').replace('Bring your interest in structural biology, biochemistry, or bioinformatics. Let’s explore what we can discover together.','Join us to study bacterial antiphage defense through structural biology, biophysics, biochemistry, microbiology, and bioinformatics.');p.write_text(s)
p=Path('Publications.html');s=p.read_text().replace('Ideas explored.<br><em>Insights shared.</em>','The mechanisms.<br><em>The published evidence.</em>').replace('A collection of our work in structural biology, bacterial immunity, and molecular transport.','Our research on bacterial antiphage defense, immune signalling, and membrane protein function.');p.write_text(s)
p=Path('assets/css/pages.css');s=p.read_text()+'''\n.home-intro .intro p+p{margin-top:18px}.defense-focus{margin-bottom:70px}.defense-focus h2{margin-bottom:28px}.defense-focus-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.defense-focus-grid>a{display:flex;flex-direction:column;padding:28px;border:1px solid var(--line);border-radius:10px;background:white;text-decoration:none}.defense-focus-grid .eyebrow{font-size:9px;color:#577444;letter-spacing:1.2px}.defense-focus-grid h3{font-size:22px;line-height:1.35;margin:18px 0 12px}.defense-focus-grid p{font-size:14px;color:var(--muted)}.focus-link{display:block;font-size:12px;font-weight:600;margin-top:auto;padding-top:22px}.defense-focus+.link-grid{margin-top:0}.home-page .hero-copy{max-width:760px}.home-page .page-hero h1{max-width:1100px}@media(max-width:800px){.defense-focus-grid{grid-template-columns:1fr}.defense-focus{margin-bottom:40px}}\n''';p.write_text(s)
p=Path('assets/css/site.css');s=p.read_text()+'''\n/* Research on membrane effectors. */\n.project-nav{grid-template-columns:repeat(6,minmax(0,1fr))}.membrane-effectors{border-top:1px solid var(--line);padding:35px 0 50px;scroll-margin-top:25px}.membrane-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:30px}.membrane-grid>article{padding:30px;border:1px solid var(--line);border-radius:10px;background:white;scroll-margin-top:30px}.membrane-grid h3{font-size:48px;letter-spacing:-2px;line-height:1.15;margin:12px 0}.membrane-grid h4{font-size:21px;line-height:1.4;margin-bottom:15px}.membrane-grid .eyebrow{font-size:9px;color:#577444;letter-spacing:1.2px}.membrane-grid p:not(.eyebrow){font-size:14px;color:var(--muted)}.membrane-grid .research-status{margin-top:16px;font-size:12px}.membrane-grid .research-status em{font-family:inherit}@media(max-width:720px){.project-nav{grid-template-columns:repeat(3,minmax(0,1fr))}.membrane-grid{grid-template-columns:1fr}.membrane-grid>article{padding:24px}.membrane-grid h3{font-size:40px}}\n''';p.write_text(s)
